import {sanitize,escapeHTML as e,plain} from './store.js';
const marker='<!--aethra-rich-->';
export const richText=value=>String(value||'').startsWith(marker)?sanitize(String(value).slice(marker.length)):e(value||'').replaceAll('\n','<br>');
export const textValue=value=>String(value||'').startsWith(marker)?plain(String(value).slice(marker.length)):String(value||'');
const presets=[['h1','Título'],['h2','Subtítulo'],['h3','Seção'],['strong','Forte'],['p','Corpo'],['small','Legenda']];
function presetMarkup(){return `<h3>Formato</h3><small class="format-caption">TEXTO</small><div class="format-presets">${presets.map(([tag,label])=>`<button type="button" data-text-preset="${tag}">${label}</button>`).join('')}</div>`;}
function decorateEditor(toolbar){
 if(toolbar.dataset.formatReady)return;toolbar.dataset.formatReady='true';toolbar.classList.add('format-drawer');
 toolbar.insertAdjacentHTML('afterbegin',presetMarkup());
 const button=document.createElement('button');button.type='button';button.className='format-launch';button.textContent='Aa · Formato';button.setAttribute('aria-expanded','false');toolbar.parentElement.querySelector('.note-editor-head').append(button);
 button.onclick=()=>{const open=toolbar.classList.toggle('format-open');button.setAttribute('aria-expanded',String(open));};
 toolbar.querySelectorAll('[data-text-preset]').forEach(b=>b.onclick=()=>{const tag=b.dataset.textPreset;if(tag==='strong'){toolbar.querySelector('[data-format=bold]').click();return;}const select=toolbar.querySelector('#blockType');select.value=tag==='small'?'p':tag;select.dispatchEvent(new Event('change'));if(tag==='small'){const size=toolbar.querySelector('#fontSize');size.value=11;size.dispatchEvent(new Event('input'));}});
}
function enhanceField(textarea){
 if(textarea.dataset.formatReady)return;textarea.dataset.formatReady='true';
 const wrap=document.createElement('div');wrap.className='rich-field';
 const name=textarea.closest('label')?.querySelector('span')?.textContent||'Texto';
 wrap.innerHTML=`<div class="rich-field-top"><span>Texto com formatação</span><button type="button" class="format-launch" aria-expanded="false">Aa · Formato</button></div><div class="field-format-panel" hidden>${presetMarkup()}<small class="format-caption">ESTILO E PARÁGRAFO</small><div class="format-commands">${[['bold','B'],['italic','I'],['underline','U'],['strikeThrough','S̶'],['insertUnorderedList','• Lista'],['insertOrderedList','1. Lista'],['justifyLeft','Esquerda'],['justifyCenter','Centro'],['justifyRight','Direita'],['justifyFull','Justificar'],['indent','Recuar +'],['outdent','Recuar −'],['removeFormat','Limpar'],['undo','↶'],['redo','↷']].map(([cmd,label])=>`<button type="button" data-command="${cmd}" title="${cmd}">${label}</button>`).join('')}</div><small class="format-caption">DECORAÇÕES</small><div class="format-commands"><button type="button" data-block="blockquote">Citação / foco</button><button type="button" data-inline="code">Código</button><button type="button" data-highlight>Marca-texto</button></div><small class="format-caption">COR</small><div class="format-swatches">${['#3c4542','#6a7b78','#a09c94','#3458a2','#6c5b96','#4b7657','#b39354','#bc7279'].map(c=>`<button type="button" data-swatch="${c}" style="background:${c}" aria-label="Cor ${c}"></button>`).join('')}<input type="color" value="#b39354" aria-label="Personalizar cor do texto"></div><label class="format-font">Fonte<select aria-label="Fonte do campo"><option value="inherit">Padrão do tema</option><option value="Georgia">Serif</option><option value="Arial">Sans</option><option value="Courier New">Mono</option></select></label></div><div class="rich-field-content" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${e(name)}">${richText(textarea.value)}</div>`;
 textarea.hidden=true;textarea.after(wrap);const input=wrap.querySelector('.rich-field-content'),panel=wrap.querySelector('.field-format-panel'),toggle=wrap.querySelector('.format-launch');let range=null;
 const sync=()=>{textarea.value=marker+sanitize(input.innerHTML);textarea.dispatchEvent(new Event('input',{bubbles:true}));};
 const capture=()=>{const s=getSelection();if(s.rangeCount&&input.contains(s.getRangeAt(0).commonAncestorContainer))range=s.getRangeAt(0).cloneRange();};
 input.addEventListener('keyup',capture);input.addEventListener('pointerup',capture);input.addEventListener('input',()=>{capture();sync();});
 function restore(){input.focus({preventScroll:true});const s=getSelection();if(range&&input.contains(range.commonAncestorContainer)){s.removeAllRanges();s.addRange(range);}else{const r=document.createRange();r.selectNodeContents(input);r.collapse(false);s.removeAllRanges();s.addRange(r);}}
 function command(cmd,value){restore();document.execCommand('styleWithCSS',false,true);document.execCommand(cmd,false,value);capture();sync();}
 toggle.onclick=()=>{capture();panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));};
 panel.onpointerdown=ev=>{capture();if(ev.target.closest('button'))ev.preventDefault();};
 panel.onclick=ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.command)command(b.dataset.command);if(b.dataset.textPreset){const tag=b.dataset.textPreset;if(tag==='strong')command('bold');else{command('formatBlock',tag==='small'?'p':tag);if(tag==='small')style('font-size','11px');}}if(b.dataset.swatch)style('color',b.dataset.swatch);if(b.dataset.block)command('formatBlock','blockquote');if(b.dataset.inline)style('font-family','monospace');if(b.hasAttribute('data-highlight'))style('background-color','#e0c58f');};
 function style(property,value){restore();const s=getSelection(),r=s.getRangeAt(0);if(r.collapsed){if(property==='color')document.execCommand('foreColor',false,value);else if(property==='background-color')document.execCommand('hiliteColor',false,value);else{input.style.setProperty(property,value);const span=document.createElement('span');span.style.setProperty(property,value);span.innerHTML=input.innerHTML;input.replaceChildren(span);} }else{const span=document.createElement('span');span.style.setProperty(property,value);span.append(r.extractContents());r.insertNode(span);r.selectNodeContents(span);s.removeAllRanges();s.addRange(r);}capture();sync();}
 panel.querySelector('input[type=color]').oninput=ev=>style('color',ev.target.value);panel.querySelector('select').onchange=ev=>style('font-family',ev.target.value==='inherit'?'serif':ev.target.value);
 input.onpaste=ev=>{ev.preventDefault();command('insertHTML',sanitize(ev.clipboardData.getData('text/html')||e(ev.clipboardData.getData('text/plain')).replaceAll('\n','<br>')));};
 textarea.form?.addEventListener('submit',()=>{if(!textarea.value.startsWith(marker)&&input.textContent.trim())sync();},true);
}
export function initFormatting(){
 let queued=false;const scan=()=>{queued=false;document.querySelectorAll('.editor-toolbar:not([data-format-ready])').forEach(decorateEditor);document.querySelectorAll('textarea:not([data-format-ready])').forEach(t=>{if(['description','motivation','conflict'].includes(t.name))enhanceField(t);});};
 new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(scan);}}).observe(document.body,{childList:true,subtree:true});scan();
 document.addEventListener('pointerdown',ev=>{document.querySelectorAll('.format-open').forEach(t=>{if(!t.contains(ev.target)&&!ev.target.closest('.format-launch')){t.classList.remove('format-open');t.parentElement.querySelector('.format-launch')?.setAttribute('aria-expanded','false');}});document.querySelectorAll('.field-format-panel:not([hidden])').forEach(p=>{if(!p.parentElement.contains(ev.target)){p.hidden=true;p.parentElement.querySelector('.format-launch').setAttribute('aria-expanded','false');}});});
}
